-- Seed QueueLess menu. Safe to rerun; IDs are stable and updates preserve menu item references.
on conflict (id) do update set name=excluded.name, category=excluded.category, price=excluded.price, prep_time_minutes=excluded.prep_time_minutes, veg=excluded.veg, popular=excluded.popular, description=excluded.description, image_url=excluded.image_url, counter_id=excluded.counter_id;
